const e=[{Claim:"Two age categories are printed: 5 years and under, and 6 to 9 years, both counted as of 16 July 2023. No lowest age is printed, so the first band starts at 3 as a placeholder; a coordinator should confirm the youngest age accepted.",SourceType:"Primary - the event's own rules document",Source:"Avonmore Fair Children's Talent Show 2023 rules and regulations",Url:"https://www.avonmorefair.ca/wp-content/uploads/Childrens-Talent-Show-Rules-Regulations-2023.pdf"},{Claim:"The show has one kind of entry, a talent act by one contestant (each contestant gives a short bio for the announcer). It is modelled as one competition, Talent Show, with one Individual group per age category. The source does not say whether group acts are allowed.",SourceType:"Primary - the event's own rules document",Source:"Avonmore Fair Children's Talent Show 2023 rules and regulations",Url:"https://www.avonmorefair.ca/wp-content/uploads/Childrens-Talent-Show-Rules-Regulations-2023.pdf"},{Claim:"Judging: 5 years and under: Overall Appearance 25, Entertainment Value 25, Talent Presentation 50. 6 to 9 years: Overall Appearance 25, Poise and Personality 25, Talent Presentation 50. Each totals 100.",SourceType:"Primary - the event's own rules document",Source:"Avonmore Fair Children's Talent Show 2023 rules and regulations",Url:"https://www.avonmorefair.ca/wp-content/uploads/Childrens-Talent-Show-Rules-Regulations-2023.pdf"},{Claim:"Scope note: cash prizes (5 and under $25, $20, $15; 6 to 9 $50, $30, $20), proof of date of birth, own music, automatic disqualification for offensive music or actions and the final decision of the judges are rules the platform has no field for; they are kept as registration-page rules and are not enforced by the software.",SourceType:"Primary - the event's own rules document",Source:"Avonmore Fair Children's Talent Show 2023 rules and regulations",Url:"https://www.avonmorefair.ca/wp-content/uploads/Childrens-Talent-Show-Rules-Regulations-2023.pdf"}],t="Built from the Avonmore Fair Children's Talent Show 2023 rules (Sunday 16 July 2023, Super Structure). Left out: ranks and grades (prizes are cash amounts only, no points for places), time limit (not printed, so 0), and the prize, music, proof-of-age and disqualification rules (no platform field; kept in the registration content). The lowest age is not printed (placeholder band 3-5, to be confirmed). Warning times are not printed and are set to 0. Only the 2023 edition was found.",a=[{GroupName:"5 and Under",AgeFrom:3,AgeTo:5,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/primary.webp"},{GroupName:"6 to 9 Years",AgeFrom:6,AgeTo:9,ParticipantTypeSetting:"Individual",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/groups/primary.webp"}],n=[{CompetitionItem:0,Title:"Talent Show",Category:109,CategoryCategoryName:"Others",ScoreLabel:1,ScoreLabelLabel:"Marks",ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp",TimeCalculation:"TotalTime"}],o=[{CompetitionItem:0,CompetitionItemTitle:"Talent Show",Group:0,GroupGroupName:"5 and Under",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:1,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"},{CompetitionItem:0,CompetitionItemTitle:"Talent Show",Group:0,GroupGroupName:"6 to 9 Years",ParticipantType:1,ParticipantTypeTitle:"Individual",Gender:3,GenderGenderTitle:"Both",Language:4,LanguageLanguageName:"Any/NA",Fees:0,MaximumMinutes:0,MaximumScore:100,MaximumSeconds:0,WarningMinute:0,WarningSecond:0,Order:2,ImageUrl:"https://justinscoderepo.github.io/etalenter-template-images/items/kids-talent-contest.webp"}],r=[{CriteriaName:"Overall Appearance",SecondValue:"25",Order:1,CompetitionItemTitle:"Talent Show",GroupGroupName:"5 and Under",ParticipantTypeTitle:"Individual"},{CriteriaName:"Entertainment Value",SecondValue:"25",Order:2,CompetitionItemTitle:"Talent Show",GroupGroupName:"5 and Under",ParticipantTypeTitle:"Individual"},{CriteriaName:"Talent Presentation",SecondValue:"50",Order:3,CompetitionItemTitle:"Talent Show",GroupGroupName:"5 and Under",ParticipantTypeTitle:"Individual"},{CriteriaName:"Overall Appearance",SecondValue:"25",Order:1,CompetitionItemTitle:"Talent Show",GroupGroupName:"6 to 9 Years",ParticipantTypeTitle:"Individual"},{CriteriaName:"Poise and Personality",SecondValue:"25",Order:2,CompetitionItemTitle:"Talent Show",GroupGroupName:"6 to 9 Years",ParticipantTypeTitle:"Individual"},{CriteriaName:"Talent Presentation",SecondValue:"50",Order:3,CompetitionItemTitle:"Talent Show",GroupGroupName:"6 to 9 Years",ParticipantTypeTitle:"Individual"}],i={Evidence:e,MaintenanceNote:t,AgeWiseGroups:a,CompetitionItems:n,CompetitionsAssignedToGroup:o,JudgesCriteria:r};export{a as AgeWiseGroups,n as CompetitionItems,o as CompetitionsAssignedToGroup,e as Evidence,r as JudgesCriteria,t as MaintenanceNote,i as default};
